from pathlib import Path
import json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

R=Path(__file__).resolve().parent;F=R/'figures';F.mkdir(exist_ok=True);D=R/'results'
cfg=json.loads((R/'config.json').read_text());audit=json.loads((R/'VALIDATION.json').read_text())
markets=pd.read_csv(D/'market_metrics.csv');models=pd.read_csv(D/'model_metrics.csv');pairs=pd.read_csv(D/'paired_metrics.csv')
ends=pd.read_csv(D/'endpoints.csv');fit=pd.read_csv(D/'same_law_refit_improvements.csv')
adoption=pd.read_csv(D/'adoption_comparisons.csv')
adequacy=pd.read_csv(D/'training_adequacy/metrics.csv').set_index(['version','capacity'])
cs={0.:'#B66B45',.5:'#728A42',1.:'#197894'}
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':9,'axes.spines.top':False,'axes.spines.right':False})
fig,ax=plt.subplots(figsize=(9,3))
for x,g in markets.groupby('x'):
 for _,s in g.groupby('seed'):ax.plot(s['round'],s.J,color=cs[x],alpha=.25,lw=.8)
 a=g.groupby('round').J.mean();ax.plot(a.index,a.values,color=cs[x],marker='o',ms=4,label=f'High-capacity share in group 1: {x:.0%}')
ax.set(xlabel='Completed slow updates',ylabel='Private-signal price precision J',title='Endogenous market after each simultaneous refit')
ax.legend(frameon=False,fontsize=8);ax.grid(alpha=.15);fig.tight_layout();fig.savefig(F/'Retraining_Price_Precision.png',dpi=180);plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(9,3))
for x,g in pairs.groupby('x'):
 a=g.groupby('round').mean(numeric_only=True);axs[0].plot(a.index,a.MSE_gain_pct,marker='o',ms=3,color=cs[x],label=f'x = {x:.0%}')
 axs[1].plot(a.index,a.private_low_pct,color=cs[x],ls='--');axs[1].plot(a.index,a.private_high_pct,color=cs[x],label=f'x = {x:.0%}')
axs[0].set(xlabel='Completed slow updates',ylabel='Width-32 MSE advantage over width 4 (%)',title='Both models evaluated on the same market law')
axs[1].set(xlabel='Completed slow updates',ylabel='Private-signal MSE improvement (%)',title='Solid: width 32; dashed: width 4')
for ax in axs:ax.grid(alpha=.15);ax.legend(frameon=False,fontsize=8)
axs[0].legend(frameon=False,fontsize=8,loc='center right',bbox_to_anchor=(1,.68))
axs[1].legend(frameon=False,fontsize=8,loc='center right',bbox_to_anchor=(1,.40))
fig.tight_layout();fig.savefig(F/'Retraining_Forecasts.png',dpi=180);plt.close(fig)

for name,file in [('D','DejaVuSans.ttf'),('DB','DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,'/usr/share/fonts/truetype/dejavu/'+file))
ss=getSampleStyleSheet()
for name,font,size,leading,col in [('TitleX','DB',19,23,'#123E50'),('HeadX','DB',12,15,'#15536A'),('BodyX','D',9,13,'#172F38'),('SmallX','D',8,11,'#405660'),('CellX','D',8,11,'#172F38')]:
 ss.add(ParagraphStyle(name=name,fontName=font,fontSize=size,leading=leading,textColor=colors.HexColor(col),spaceAfter=7 if name!='CellX' else 0))
story=[]
def p(s,style='BodyX'):story.append(Paragraph(s,ss[style]))
def title(s):p(s,'TitleX')
def heading(s):story.append(Spacer(1,3));p(s,'HeadX')
def table(rows,widths):
 t=Table([[Paragraph(str(x),ss['CellX']) for x in row] for row in rows],colWidths=widths,hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E6EFF3')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F3F6F8')]),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.extend([t,Spacer(1,8)])

title('Slow-fast retraining with endogenous prices')
p('Implementation and numerical pilot | 28 October 2026 | GRU widths 4 and 32')
p('The market now generates the prices used in the next training round. During each fast stage, every forecasting rule is fixed while many auctions clear recursively. Only after the entire data bank is generated are the models refitted. All new rules are then deployed together. This implements the separation in S3 between a fixed-policy market and the slower model-update process.')
heading('1. The implemented loop')
table([['Stage','What changes','What stays fixed'],['Fast: generate market data','Public states, prices, price histories and realized forecasts','All encoder weights, head coefficients and normalizations'],['Slow: refit on that bank','Both GRUs and the second group\'s private/price head','The complete data bank and adoption share'],['Next fast stage','Prices generated by the updated profile','The newly updated parameters throughout that stage']],[145,195,190])
p('Current price enters the demand schedule, but never the current encoder. After clearing, it becomes the next period\'s lagged-price input. Each GRU recomputes its 16-period window from a zero hidden state, exactly as in its supervised training class. Parallel simulation paths are independent; windows never cross path boundaries.','SmallX')
heading('2. Price precision across slow updates')
story.append(Image(str(F/'Retraining_Price_Precision.png'),width=530,height=176.7))
ee=ends.groupby('x').mean(numeric_only=True)
table([['Upgraded share x','Initial frozen-market J','J after six updates','Change from initial'],*[[f'{x:.0%}',f'{r.J_initial:.4f}',f'{r.J_final:.4f}',f'{r.J_change_pct:+.2f}%'] for x,r in ee.iterrows()]],[130,140,130,130])
p('Thick lines are means of three initial training seeds; thin lines show individual trajectories. x is the upgraded fraction of the first investor group, which has total mass 0.55. The second group has mass 0.45 and retains its own information class. J = A^2 / 0.9^2 measures the precision of the private-fundamental price signal, not total price information or welfare.','SmallX')
ad=adoption[adoption['round']==6].groupby('x').J_vs_zero_adoption_pct.mean()
p(f'At update six, J is {-ad.loc[.5]:.2f}% lower at x = 50% and {-ad.loc[1.]:.2f}% lower at x = 100% than in the x = 0% market at the same update (mean paired differences). The zero-adoption market also retrains.','SmallX')
story.append(PageBreak())

title('Forecasting and trading after markets adjust')
heading('3. Prediction comparisons use a common market law')
story.append(Image(str(F/'Retraining_Forecasts.png'),width=490,height=163.3))
table([['x','Final large-model MSE advantage','Final private value: width 4','Final private value: width 32'],*[[f'{x:.0%}',f'{r.MSE_gain_final:.2f}%',f'{r.private_low_final:.2f}%',f'{r.private_high_final:.2f}%'] for x,r in ee.iterrows()]],[65,155,155,155])
p('Both capacities are evaluated on the same endogenous market. A zero-share model is fitted but does not enter clearing. Private value is the MSE reduction from adding the private signal to independently calibrated affine heads, with the encoder and current price held fixed. It is not monetary upgrade value.')
heading('4. Every investor type can respond to the new law')
p('Group 1 updates both GRUs and all mean/variance head parameters. Group 2 still uses only its private signal and current price, but refits its coefficients and residual variance by least squares. Non-upgrading investors therefore also learn from the changed market.')
table([['x','Change in group 1 contribution to A','Change in group 2 contribution to A'],*[[f'{x:.0%}',f'{r.A_group1_change:+.5f}',f'{r.A_other_change:+.5f}'] for x,r in ee.iterrows()]],[65,232,233])
p('A = 0.55(1-x) iota_L + 0.55x iota_H + 0.45 iota_2. Changes are from round zero to six and sum to the change in A. Since J = A^2 / 0.9^2, group 2\'s weaker response outweighs group 1\'s stronger response in these runs.')
heading('5. Separate refitting gains from a change of market')
p('We first test updated models on independent data from their training market Q_n, then on the new market Q_(n+1) they generate. These tables separate learning under a fixed law from performance after prices adjust. MSE changes across different laws combine both effects.')
p('Neural policies are deployed as trained; independently fitted neural heads are diagnostics only. In Model A, beta and v stay constant within each fast stage, so J changes across slow rounds only through model updates.','SmallX')
story.append(PageBreak())

title('Data volume, verification and interpretation')
heading('6. A complete generated bank precedes every update')
table([['Item','Specification'],['Initial models','First three confirmed V2 seed pairs: 18013, 19031, 20047'],['Adoption / slow updates','x = 0%, 50%, 100%; six updates per trajectory; 63 deployed states'],['Training data per update','512 independent paths x 2,048 usable periods = 1,048,576 observations'],['Burn-in / context','512 discarded periods per path; exact 16-period finite window'],['Independent data per update','Validation 65,536; head calibration 65,536; evaluation 131,072'],['Neural refitting','Warm start; eight disjoint chunks; 4,096 optimizer steps per model'],['Optimization','Adam .001 for five chunks, then decay to .00001 over three; batch 256'],['Other controls','Weight penalty 1e-5; clip norm 3; frozen initial normalization; no early stopping']],[170,360])
p('Primitive shocks are matched across adoption rates. Training banks are fresh between slow updates. Held-out evaluation primitives are common across updates to sharpen comparisons and are never used by the optimizer or for checkpoint selection. All data-generation metadata identify the deployed profile, seed, bank, burn-in and path lengths.','SmallX')
heading('7. Verification')
p(f"Six implementation tests pass, including independently recomputed demand clearing, an analytically solvable constant-policy market, future-payoff exclusion, inactive-capacity isolation, path boundaries and frozen model fingerprints. All {audit['complete_deployed_states']} completed states have been audited. Data generation finishes before learning starts, and saved next-round models match the next deployed checkpoints exactly.")
p(f"Maximum market-clearing residual: {audit['max_clearing_error']:.2e}. Maximum retained price difference from initial prices -10 versus +10 under identical future shocks: {audit['max_initial_price_coupling_error']:.2e}. Minimum aggregate clearing slope: {audit['minimum_clearing_slope']:.4f}. Maximum absolute neural price coefficient: {audit['max_neural_abs_price_slope']:.4f} (bound 0.45). Split-path mean and variance diagnostics are retained in fast_checks.csv.",'SmallX')
heading('8. What these runs establish')
settled=sum(r['within_tolerance'] for r in audit['convergence'])
p(f"This is a functioning finite-sample slow-fast retraining experiment. Under a descriptive criterion requiring relative changes below 0.5% in J and each type's MSE, beta and v for the last three updates, {settled}/9 trajectories qualify. That criterion measures empirical settling of selected observables; it does not prove a population fixed point or global optimality of neural training.")
p('All trajectories start from the same inherited trained profile for a given seed. Round zero is its frozen-policy market at the indicated adoption rate, not a separately solved all-low retraining equilibrium. A subsequent adoption-shock experiment can start from a validated all-low stationary retraining state. The present three-seed implementation pilot is not a new ten-seed confirmation or an S5 utility test.')
p('On the first x = 50% update for seed 18013, one pass through 1,048,576 additional observations from the same law improves MSE by 0.019% (width 4) and 0.015% (width 32). Trading sensitivity still changes by -1.41% and -0.85%. These diagnostic models are not deployed in the main trajectories; numerical settling would not establish exact policy optimality.','SmallX')
p('The archive contains code, tests, all checkpoints, generated-law provenance and results. Intermediate banks are reproducible from saved models and seeds. The manuscript is unchanged.','SmallX')

def footer(canvas,doc):
 canvas.setStrokeColor(colors.HexColor('#C9D8DE'));canvas.line(41,36,571,36);canvas.setFont('D',7);canvas.setFillColor(colors.HexColor('#58707E'))
 canvas.drawString(41,24,'28 October 2026 | Slow-fast retraining, V1 | Manuscript unchanged');canvas.drawRightString(571,24,str(doc.page))
out=F/'S4_Slow_Fast_Retraining_v1.pdf'
SimpleDocTemplate(str(out),pagesize=(612,792),leftMargin=41,rightMargin=41,topMargin=37,bottomMargin=48,title='Slow-fast retraining with endogenous prices').build(story,onFirstPage=footer,onLaterPages=footer)
print(out)
